function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

  shader(sh);

  sh.setUniform("u_resolution", [width, height]);
  sh.setUniform("u_time", millis() / 1000.0);
  sh.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

